If you want to use routing, create an entry component that will be routed to.

#### Entry Component (`entry.component.ts`)

```typescript
import { Component } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-entry',
  templateUrl: './entry.component.html'
})
export class EntryComponent {
  constructor(private router: Router) {}

  navigateToTextEditor() {
    this.router.navigate(['/text-editor']);
  }

  navigateToMultiSelectList() {
    this.router.navigate(['/multi-select-list']);
  }
}
```

#### Route Configuration (`app-routing.module.ts`)

```typescript
import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
